js1m2.inicial:
// 1. Pontos da equipe (7 * 15)
// 2. Média de pontos (250 / 8)
// 3. Jogadores de fora (23 % 4)
// 4. Caminhos da pista (2 ** 5)
// 5. Prêmio da campeã: 3 * 15 + 10, em dobro

testes:
const codigo = textoDoCodigo({ semComentarios: true });
const contas = [
  [/7\s*\*\s*15|15\s*\*\s*7/, "Calcule os pontos da equipe com 7 * 15."],
  [/250\s*\/\s*8/, "Calcule a média com 250 / 8."],
  [/23\s*%\s*4/, "Descubra quem fica de fora com o resto da divisão: 23 % 4."],
  [/2\s*\*\*\s*5/, "Calcule os caminhos com a potência 2 ** 5."],
];
for (const [conta, msg] of contas) verificar(conta.test(codigo), msg);

const dobrada = acharNos("BinaryExpression").some((n) => n.operator === "*" &&
  [n.left, n.right].some((lado) => lado.type === "BinaryExpression" && lado.operator === "+"));
verificar(dobrada,
  "No prêmio da campeã, a soma (3 * 15 + 10) precisa acontecer antes de multiplicar por 2: coloque a soma entre parênteses e o * 2 do lado de fora.");

const r = rodar();
saidaIgual(r, "60");
usaOperador("*", "Deixe o JavaScript fazer a conta 15 * 4, em vez de escrever o 60.");

js1m3.inicial:
// Formato: console.log("Nível " + 2 * 3);
// 1. Horas da semana (7 * 24)
// 2. Pontos da partida (60 + 45, entre parênteses)
// 3. Preço dos ingressos (3 * 25)

testes:
const r = rodar();
saidaIgual(r, [
  "Uma semana tem 168 horas.",
  "Pontos da partida: 105",
  "Ingresso para 3 pessoas: R$ 75",
]);

const codigo = textoDoCodigo({ semComentarios: true });
const contas = [
  [/7\s*\*\s*24|24\s*\*\s*7/, "Calcule as horas da semana com 7 * 24."],
  [/60\s*\+\s*45|45\s*\+\s*60/, "Some as duas rodadas da partida: (60 + 45)."],
  [/3\s*\*\s*25|25\s*\*\s*3/, "Calcule o preço dos ingressos com 3 * 25."],
];
for (const [conta, msg] of contas) verificar(conta.test(codigo), msg);

const logs = chamadas("console.log");
verificar(logs.length >= 3, "Use um console.log para cada frase: são três frases, então são três console.log.");
const comVirgula = logs.find((c) => c.arguments.length !== 1);
verificar(!comVirgula,
  `Na linha ${comVirgula ? comVirgula.linha : ""}, junte o texto e o número com + num valor só, em vez de separar com vírgulas: console.log("Uma semana tem " + 7 * 24 + " horas.");`);
usaOperador("+", "Use o + para juntar os textos e os números.");

js1m3.solucao:
console.log("Uma semana tem " + 7 * 24 + " horas.");
console.log("Pontos da partida: " + (60 + 45));
console.log("Ingresso para 3 pessoas: R$ " + 3 * 25);

testes:
const r = rodar();
saidaIgual(r, "Moedas: 15");
usaOperador("*", "Calcule as moedas com 3 * 5, dentro do console.log.");

verificar(chamadas("console.log").every((c) => c.arguments.length === 1),
  'Junte o texto e a conta com +, sem vírgula: console.log("Moedas: " + 3 * 5);');
usaOperador("+", 'Use o + para juntar o texto e a conta: console.log("Moedas: " + 3 * 5);');

js1m4.inicial:
