console.log("1 x Hambúrguer: R$ 18");
console.log("1 x Sorvete de alho: R$ 9");
console.log("1 x Suco de laranja: R$ 7");
console.log("1 x Pizza de meia: R$ 25");
console.log("Total: R$ " + (18 + 7));

testes:
const deLinha = comentarios().filter((c) => c.tipo === "linha");
for (const item of ["Sorvete de alho", "Pizza de meia"]) {
  verificar(deLinha.some((c) => c.texto.includes(item)),
    `Comente a linha do "${item}" colocando // no começo dela — não apague a linha.`);
}

const blocos = comentarios().filter((c) => c.tipo === "bloco" && !c.texto.includes("console.log"));
verificar(blocos.some((c) => c.texto.replace(/[\s*]/g, "").length >= 10),
  "Escreva no começo do arquivo um comentário de bloco, entre /* e */, com uma frase explicando o que o programa faz. Por exemplo: /* Mostra o pedido 42 da lanchonete */");

