js1m5.inicial:
// Recibo da Lanchonete do Pixel
// 1. Título
console.log("=== LANCHONETE DO PIXEL ===");
// 2. X-burgers (2 * 18) e sucos (3 * 7)
// 3. Total
// 4. Pago e troco
// 5. Linha em branco
// 6. Notas de 10 no troco (Math.floor)
// 7. Moedas de 1 no troco (%)

testes:
const codigo = textoDoCodigo({ semComentarios: true });
verificar(/2\s*\*\s*18|18\s*\*\s*2/.test(codigo), "Calcule o preço dos X-burgers com 2 * 18.");
verificar(/3\s*\*\s*7|7\s*\*\s*3/.test(codigo), "Calcule o preço dos sucos com 3 * 7.");
usaOperador("-", "Calcule o troco com uma subtração: 100 menos o total.");

const prontos = acharNos("Literal").filter((n) =>
  (typeof n.value === "number" && [36, 21, 57, 43].includes(n.value)) ||
  (typeof n.value === "string" && /R\$ (36|21|57|43)\b/.test(n.value)));
verificar(prontos.length === 0,
  `Na linha ${prontos.length ? prontos[0].linha : ""} há um resultado escrito à mão. Deixe o JavaScript calcular preços, total e troco.`);

js1m5.solucao:
console.log("=== LANCHONETE DO PIXEL ===");
console.log("2 x X-burger: R$ " + 2 * 18);
console.log("3 x Suco: R$ " + 3 * 7);
console.log("Total: R$ " + (2 * 18 + 3 * 7));
console.log("Pago: R$ " + 100);
console.log("Troco: R$ " + (100 - (2 * 18 + 3 * 7)));
console.log();
console.log("Notas de 10 no troco: " + Math.floor((100 - (2 * 18 + 3 * 7)) / 10));
console.log("Moedas de 1 no troco: " + (100 - (2 * 18 + 3 * 7)) % 10);

testes:
const r = rodar();
saidaIgual(r, "4");
usaChamada("Math.floor", "Arredonde para baixo com Math.floor(47 / 10), em vez de escrever o 4.");
